1	//! Reading a `.fjgraphic` package (spec §11 G-47 (c)): the archive's checks,
2	//! the manifest's, and the two held against each other. The app hands in the
3	//! file's bytes and copies what this answers; nothing here touches a file.
4	//!
5	//! **The checks run in order**, as spec §11 G-47 (c) lists them, and the
6	//! first that fails is the answer: a lowercase sentence naming the value.
7	//!
8	//! **The answer** is the manifest re-written in G-46 (c)'s key order with
9	//! each file's `offset`, the byte offset of its data in the package.
10	
11	use std::collections::HashSet;
12	
13	use serde_json::{json, Map, Value};
14	use sha2::{Digest, Sha256};
15	
16	use crate::graphic_package::{
17	    crc32, hex, is_legal, CENTRAL_FIXED, END_RECORD, LOCAL_FIXED, MANIFEST,
18	};
19	use crate::model_graphic::check_name;
20	
21	/// The longest project-folder name a manifest may give: G-23's 247 bytes
22	/// (255 less `.partial`, which the app's write adds first).
23	const MAX_PROJECT_NAME: usize = 247;
24	/// The longest archive comment, so how far back the end record may sit.
25	const MAX_COMMENT: usize = 65_535;
26	/// A 32-bit field that says "see the Zip64 record".
27	const ZIP64: u32 = 0xFFFF_FFFF;
28	const END_SIGNATURE: u32 = 0x0605_4b50;
29	const CENTRAL_SIGNATURE: u32 = 0x0201_4b50;
30	const LOCAL_SIGNATURE: u32 = 0x0403_4b50;
31	
32	/// One archive entry: its name, its data, and where that data starts.
33	struct Entry<'a> {
34	    name: String,
35	    data: &'a [u8],
36	    at: usize,
37	}
38	
39	/// One file the manifest lists.
40	struct Listed {
41	    path: String,
42	    name: String,
43	    size: u64,
44	    sha256: String,
45	}
46	
47	/// Checks the package in `data` and answers its manifest with each file's
48	/// offset, or the first check's refusal.
49	pub(crate) fn read(data: &[u8]) -> Result<String, String> {
50	    let entries = entries(data)?;
51	    let Some(first) = entries.first() else {
52	        return Err(format!("the package holds no entries, so no {MANIFEST}"));
53	    };
54	    if first.name != MANIFEST {
55	        return Err(format!(
56	            "the first entry is \"{}\", not \"{MANIFEST}\"",
57	            first.name
58	        ));
59	    }
60	    let (mut manifest, module, files) = manifest(first.data)?;
61	    let rest = &entries[1..];
62	    let present: Vec<&str> = rest.iter().map(|e| e.name.as_str()).collect();
63	    let listed: Vec<&str> = files.iter().map(|f| f.path.as_str()).collect();
64	    if present != listed {
65	        return Err(format!(
66	            "the package's entries are {}, but the manifest lists {}",
67	            joined(&present),
68	            joined(&listed)
69	        ));
70	    }
71	    let mut answered = Vec::with_capacity(files.len());
72	    for (file, entry) in files.iter().zip(rest) {
73	        if entry.data.len() as u64 != file.size {
74	            return Err(format!(
75	                "{} is {} bytes, but the manifest says {}",
76	                file.path,
77	                entry.data.len(),
78	                file.size
79	            ));
80	        }
81	        let sha = hex(&Sha256::digest(entry.data));
82	        if sha != file.sha256 {
83	            return Err(format!(
84	                "{}'s SHA-256 is {sha}, but the manifest says {}",
85	                file.path, file.sha256
86	            ));
87	        }
88	        answered.push(json!({
89	            "path": file.path, "name": file.name, "size": file.size, "sha256": sha,
90	            "offset": entry.at,
91	        }));
92	    }
93	    if std::str::from_utf8(rest[0].data).is_err() {
94	        return Err(format!("{module}.js is not UTF-8 text"));
95	    }
96	    manifest["files"] = Value::Array(answered);
97	    serde_json::to_string(&manifest).map_err(|e| format!("the manifest could not be answered: {e}"))
98	}
99	
100	/// `"a", "b"`, or `nothing`.
101	fn joined(names: &[&str]) -> String {
102	    if names.is_empty() {
103	        return "nothing".to_string();
104	    }
105	    let quoted: Vec<String> = names.iter().map(|n| format!("\"{n}\"")).collect();
106	    quoted.join(", ")
107	}
108	
109	fn u16_at(b: &[u8], at: usize) -> u16 {
110	    u16::from_le_bytes([b[at], b[at + 1]])
111	}
112	
113	fn u32_at(b: &[u8], at: usize) -> u32 {
114	    u32::from_le_bytes([b[at], b[at + 1], b[at + 2], b[at + 3]])
115	}
116	
117	/// The end record's offset: the last signature within the last 22 + 65,535
118	/// bytes whose comment ends the file.
119	fn end_record(data: &[u8]) -> Result<usize, String> {
120	    let not_zip = || "the package is not a zip: no end of central directory record".to_string();
121	    let last = data.len().checked_sub(END_RECORD).ok_or_else(not_zip)?;
122	    let first = last.saturating_sub(MAX_COMMENT);
123	    (first..=last)
124	        .rev()
125	        .find(|&at| {
126	            u32_at(data, at) == END_SIGNATURE
127	                && at + END_RECORD + usize::from(u16_at(data, at + 20)) == data.len()
128	        })
129	        .ok_or_else(not_zip)
130	}
131	
132	/// Every entry, in central-directory order, each checked.
133	fn entries(data: &[u8]) -> Result<Vec<Entry<'_>>, String> {
134	    let end = end_record(data)?;
135	    let (disk, central_disk) = (u16_at(data, end + 4), u16_at(data, end + 6));
136	    let (here, total) = (u16_at(data, end + 8), u16_at(data, end + 10));
137	    let (central_len, central_at) = (u32_at(data, end + 12), u32_at(data, end + 16));
138	    if here == 0xFFFF || total == 0xFFFF || central_len == ZIP64 || central_at == ZIP64 {
139	        return Err(
140	            "the package's end record points to Zip64; a .fjgraphic is a zip without Zip64"
141	                .to_string(),
142	        );
143	    }
144	    if disk != 0 || central_disk != 0 {
145	        return Err(format!(
146	            "the package spans disks (disk {disk}, central directory on {central_disk}); a .fjgraphic is one file"
147	        ));
148	    }
149	    if here != total {
150	        return Err(format!(
151	            "the end record counts {here} entries on this disk but {total} in all"
152	        ));
153	    }
154	    let central_at = central_at as usize;
155	    let central_end = central_at + central_len as usize;
156	    if central_end > end {
157	        return Err(format!(
158	            "the central directory (bytes {central_at} to {central_end}) runs past the end record at {end}"
159	        ));
160	    }
161	    let mut out: Vec<Entry> = Vec::with_capacity(usize::from(total));
162	    let mut seen = HashSet::new();
163	    let mut at = central_at;
164	    for index in 0..usize::from(total) {
165	        let damaged = || format!("central directory entry {index} is damaged");
166	        if at + CENTRAL_FIXED > central_end || u32_at(data, at) != CENTRAL_SIGNATURE {
167	            return Err(damaged());
168	        }
169	        let flags = u16_at(data, at + 8);
170	        let method = u16_at(data, at + 10);
171	        let crc = u32_at(data, at + 16);
172	        let (compressed, size) = (u32_at(data, at + 20), u32_at(data, at + 24));
173	        let name_len = usize::from(u16_at(data, at + 28));
174	        let skipped = usize::from(u16_at(data, at + 30)) + usize::from(u16_at(data, at + 32));
175	        let local = u32_at(data, at + 42);
176	        let name_end = at + CENTRAL_FIXED + name_len;
177	        let next = name_end + skipped;
178	        if next > central_end {
179	            return Err(damaged());
180	        }
181	        let raw_name = &data[at + CENTRAL_FIXED..name_end];
182	        let name = std::str::from_utf8(raw_name)
183	            .map_err(|_| format!("central directory entry {index}'s name is not UTF-8"))?
184	            .to_string();
185	        if method != 0 {
186	            return Err(format!(
187	                "{name} is compressed (method {method}); a .fjgraphic holds stored entries only"
188	            ));
189	        }
190	        if flags & 0x0009 != 0 {
191	            return Err(format!("{name} is encrypted or has a data descriptor (flags {flags:#06x}); a .fjgraphic holds neither"));
192	        }
193	        if compressed == ZIP64 || size == ZIP64 || local == ZIP64 {
194	            return Err(format!(
195	                "{name} uses Zip64 (a field of 0xFFFFFFFF); a .fjgraphic is a zip without Zip64"
196	            ));
197	        }
198	        if compressed != size {
199	            return Err(format!(
200	                "{name} is stored but its compressed size {compressed} is not its size {size}"
201	            ));
202	        }
203	        if name.ends_with('/') {
204	            return Err(format!(
205	                "{name} is a folder entry; a .fjgraphic holds files only"
206	            ));
207	        }
208	        if !seen.insert(name.clone()) {
209	            return Err(format!("{name} is in the package twice"));
210	        }
211	        let local = local as usize;
212	        let disagrees = || {
213	            format!("{name}'s local header is missing or does not agree with the central directory")
214	        };
215	        if local + LOCAL_FIXED > central_at || u32_at(data, local) != LOCAL_SIGNATURE {
216	            return Err(disagrees());
217	        }
218	        let local_name_len = usize::from(u16_at(data, local + 26));
219	        let local_extra = usize::from(u16_at(data, local + 28));
220	        let start = local + LOCAL_FIXED + local_name_len + local_extra;
221	        if start > central_at
222	            || u16_at(data, local + 8) != method
223	            || u32_at(data, local + 18) != compressed
224	            || u32_at(data, local + 22) != size
225	            || &data[local + LOCAL_FIXED..local + LOCAL_FIXED + local_name_len] != raw_name
226	        {
227	            return Err(disagrees());
228	        }
229	        let stop = start + size as usize;
230	        if stop > central_at {
231	            return Err(format!(
232	                "{name}'s data (bytes {start} to {stop}) runs past the central directory at {central_at}"
233	            ));
234	        }
235	        let bytes = &data[start..stop];
236	        let actual = crc32(bytes);
237	        if actual != crc {
238	            return Err(format!(
239	                "{name}'s CRC-32 is {actual:08x}, but the archive says {crc:08x}"
240	            ));
241	        }
242	        out.push(Entry {
243	            name,
244	            data: bytes,
245	            at: start,
246	        });
247	        at = next;
248	    }
249	    Ok(out)
250	}
251	
252	/// A value as a refusal names it; a missing key is `nothing`.
253	fn shown(value: Option<&Value>) -> String {
254	    value.map_or_else(|| "nothing".to_string(), Value::to_string)
255	}
256	
257	fn string(object: &Map<String, Value>, key: &str, what: &str) -> Result<String, String> {
258	    match object.get(key) {
259	        Some(Value::String(text)) => Ok(text.clone()),
260	        other => Err(format!("{what} must be a string, not {}", shown(other))),
261	    }
262	}
263	
264	/// The manifest's fields in G-46 (c)'s order (less `files`), the module's
265	/// name, and the files it lists.
266	fn manifest(bytes: &[u8]) -> Result<(Value, String, Vec<Listed>), String> {
267	    let text = std::str::from_utf8(bytes).map_err(|_| format!("{MANIFEST} is not UTF-8 text"))?;
268	    let value: Value =
269	        serde_json::from_str(text).map_err(|e| format!("{MANIFEST} is not JSON: {e}"))?;
270	    let Some(object) = value.as_object() else {
271	        return Err(format!("{MANIFEST} must be an object, not {value}"));
272	    };
273	    match object.get("fjgraphic").and_then(Value::as_u64) {
274	        Some(1) => {}
275	        Some(n) if n > 1 => {
276	            return Err(format!(
277	            "the package is format {n}; this Frame Job reads format 1 — a newer Frame Job wrote it"
278	        ))
279	        }
280	        _ => {
281	            return Err(format!(
282	                "fjgraphic must be 1, not {}",
283	                shown(object.get("fjgraphic"))
284	            ))
285	        }
286	    }
287	    let module = string(object, "module", "module")?;
288	    check_name(&module)?;
289	    let title = string(object, "title", "title")?;
290	    let category = string(object, "category", "category")?;
291	    let description = match object.get("description") {
292	        Some(Value::String(text)) => Value::String(text.clone()),
293	        Some(Value::Null) => Value::Null,
294	        other => {
295	            return Err(format!(
296	                "description must be a string or null, not {}",
297	                shown(other)
298	            ))
299	        }
300	    };
301	    let app_version = string(object, "app_version", "app_version")?;
302	    let files = files(object, &module)?;
303	    let out = json!({
304	        "fjgraphic": 1, "module": module, "title": title, "category": category,
305	        "description": description, "app_version": app_version,
306	    });
307	    Ok((out, module, files))
308	}
309	
310	/// U+0000–U+001F and U+007F–U+009F.
311	fn is_control(c: char) -> bool {
312	    matches!(c as u32, 0..=0x1F | 0x7F..=0x9F)
313	}
314	
315	/// A project-folder name: 1 to 247 bytes, no `/`, no control scalar, no
316	/// leading `.`.
317	fn is_project_name(name: &str) -> bool {
318	    !name.is_empty()
319	        && name.len() <= MAX_PROJECT_NAME
320	        && !name.starts_with('.')
321	        && !name.chars().any(|c| c == '/' || is_control(c))
322	}
323	
324	/// `files`, each checked; the first is the module.
325	fn files(object: &Map<String, Value>, module: &str) -> Result<Vec<Listed>, String> {
326	    let Some(Value::Array(list)) = object.get("files") else {
327	        return Err(format!(
328	            "files must be an array, not {}",
329	            shown(object.get("files"))
330	        ));
331	    };
332	    if list.is_empty() {
333	        return Err(format!(
334	            "files must begin with \"{module}.js\", not be empty"
335	        ));
336	    }
337	    let module_file = format!("{module}.js");
338	    let mut out = Vec::with_capacity(list.len());
339	    let mut names = HashSet::new();
340	    for (index, file) in list.iter().enumerate() {
341	        let empty = Map::new();
342	        let fields = file.as_object().unwrap_or(&empty);
343	        let path = string(fields, "path", &format!("files[{index}].path"))?;
344	        let name = string(fields, "name", &format!("files[{index}].name"))?;
345	        let Some(size) = fields.get("size").and_then(Value::as_u64) else {
346	            return Err(format!(
347	                "files[{index}].size must be a whole number of bytes, not {}",
348	                shown(fields.get("size"))
349	            ));
350	        };
351	        let sha256 = match fields.get("sha256") {
352	            Some(Value::String(sha))
353	                if sha.len() == 64
354	                    && sha
355	                        .bytes()
356	                        .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)) =>
357	            {
358	                sha.clone()
359	            }
360	            other => {
361	                return Err(format!(
362	                    "files[{index}].sha256 must be 64 lowercase hex digits, not {}",
363	                    shown(other)
364	                ))
365	            }
366	        };
367	        if index == 0 {
368	            if path != module_file || name != module_file {
369	                return Err(format!(
370	                    "the first file must be \"{module_file}\" in both path and name, not path \"{path}\" and name \"{name}\""
371	                ));
372	            }
373	        } else {
374	            let folder = ["fonts", "assets"]
375	                .into_iter()
376	                .find(|f| path.strip_prefix(f).is_some_and(|n| n.starts_with('/')));
377	            let legal = folder.is_some_and(|f| is_legal(&path[f.len() + 1..]));
378	            let Some(folder) = folder.filter(|_| legal) else {
379	                return Err(format!(
380	                    "file \"{path}\" is not fonts/<name> or assets/<name> with a name the package can hold"
381	                ));
382	            };
383	            if !is_project_name(&name) {
384	                return Err(format!(
385	                    "files[{index}].name \"{name}\" is not a file name (1 to {MAX_PROJECT_NAME} bytes, no /, no control character, no leading .)"
386	                ));
387	            }
388	            if !names.insert((folder, name.clone())) {
389	                return Err(format!("\"{name}\" is listed twice in {folder}/"));
390	            }
391	        }
392	        out.push(Listed {
393	            path,
394	            name,
395	            size,
396	            sha256,
397	        });
398	    }
399	    Ok(out)
400	}
