    override class var writableTypes: [String] { [projectTypeIdentifier] }

    override func writableTypes(for saveOperation: NSDocument.SaveOperationType) -> [String] {
        // A project only ever writes itself. Export (⌘E) is a different verb
        // with its own sheet (spec §7.8) and deliberately not a save format.
        [Self.projectTypeIdentifier]
    }

    /// A package document autosaves safely: NSDocument writes the whole
    /// wrapper to a sibling location and swaps, so a crash mid-save cannot
    /// leave half a package behind.
    override class var autosavesInPlace: Bool { true }

    override func fileNameExtension(
        forType typeName: String, saveOperation: NSDocument.SaveOperationType
    ) -> String? {
        cancelSources()
        let files = FileManager.default
        var exists = files.fileExists(atPath: watchedFolder.path)
        if !exists, watchedPackage == nil {
            try? files.createDirectory(at: watchedFolder, withIntermediateDirectories: true)
            exists = files.fileExists(atPath: watchedFolder.path)
        }
        guard exists else {
            let unwatched = watchedPackage.flatMap { arm($0, folder: true, g) }
            return (.empty(warnings: unwatched.map { [$0] } ?? []), false)
        }
        var warnings: [String] = []
        let fonts = watchedFolder.appendingPathComponent(Self.fontsFolderName, isDirectory: true)
        let assets = watchedFolder.appendingPathComponent(Self.assetsFolderName, isDirectory: true)
        for folder in [watchedFolder, fonts, assets] where files.fileExists(atPath: folder.path) {
            if let unwatched = arm(folder, folder: true, g) { warnings.append(unwatched) }
        }
        var moduleURLs: [URL] = []
        for url in listing(watchedFolder) where url.pathExtension == "js" {
            guard Self.isModuleName(url.deletingPathExtension().lastPathComponent) else {
                warnings.append("\(Self.folderName)/\(url.lastPathComponent) \(Self.nameRule)")
                continue
            }
            moduleURLs.append(url)
        }
        let fontURLs = listing(fonts).filter {
            Self.fontExtensions.contains($0.pathExtension.lowercased())
        }
        var assetURLs: [URL] = []
        for url in listing(assets)
        where Self.assetExtensions.contains(url.pathExtension.lowercased()) {
            guard GraphicAssetName.isLegal(url.lastPathComponent) else {
                warnings.append("\(Self.relative(url)) \(GraphicAssetName.rule) and was skipped")
                continue
            }
            assetURLs.append(url)
        }
        for url in (moduleURLs + fontURLs + assetURLs).prefix(Self.fileSourceLimit) {
            if let unwatched = arm(url, folder: false, g) { warnings.append(unwatched) }
        }
        var modules: [String: GraphicModuleFile] = [:]
        for url in moduleURLs {
            let name = url.deletingPathExtension().lastPathComponent
            guard let bytes = try? Data(contentsOf: url) else { continue }
            modules[name] = GraphicModuleFile(
                name: name, url: url, bytes: bytes, revision: Self.hex(SHA256.hash(data: bytes)))
        }
        let (fontFiles, fontWarnings) = validatedFonts(fontURLs)
        warnings += fontWarnings
        var assetFiles: [GraphicFile] = []
        for url in assetURLs {
            guard let bytes = try? Data(contentsOf: url) else { continue }
            // An empty `Data` crosses the FFI as NULL, which `addAsset` refuses.
            guard !bytes.isEmpty else {
                warnings.append("\(Self.relative(url)) is empty and was skipped")
                continue
            }
            assetFiles.append(GraphicFile(name: url.lastPathComponent, url: url, bytes: bytes))
        }
        var hasher = SHA256()
        for file in fontFiles + assetFiles {
            hasher.update(data: Data(file.name.utf8))
            hasher.update(data: file.bytes)
        }
        let found = GraphicScan(
            modules: modules, fonts: fontFiles, assets: assetFiles,
            libraryVersion: Self.hex(hasher.finalize()), warnings: warnings)
        return (found, true)
    }
}

/// One font file's last verdict: the accepted file, or the refusal's warning.
struct GraphicFontVerdict {
    let identity: GraphicFontIdentity
    let file: GraphicFile?
    let warning: String?
}

extension GraphicStore {
    /// Queue only. Answers the accepted fonts and the refusal warnings in `urls` order;
    /// prunes `fontVerdicts` to `urls`.
    func validatedFonts(_ urls: [URL]) -> (fonts: [GraphicFile], warnings: [String]) {
        var fonts: [GraphicFile] = []
        var warnings: [String] = []
        var kept: [String: GraphicFontVerdict] = [:]
        for url in urls {
            let key = url.standardizedFileURL.path
            let identity = GraphicFontIdentity(of: url)
            let verdict: (file: GraphicFile?, warning: String?)
            if let cached = fontVerdicts[key], let identity = identity,
                cached.identity == identity
            {
                verdict = (cached.file, cached.warning)
            } else {
                // An unreadable file is skipped silently, as the scan always did.
                guard let bytes = try? Data(contentsOf: url) else { continue }
                do {
                    try GraphicLibrary().addFont(bytes)
                    let file = GraphicFile(name: url.lastPathComponent, url: url, bytes: bytes)
                    verdict = (file, nil)
                } catch {
                    verdict = (nil, "\(Self.relative(url)): \(error.localizedDescription)")
                }
            }
            if let file = verdict.file { fonts.append(file) }
            if let warning = verdict.warning { warnings.append(warning) }
            if let identity = identity {
                kept[key] = GraphicFontVerdict(
                    identity: identity, file: verdict.file, warning: verdict.warning)
            }
        }
        fontVerdicts = kept
        return (fonts, warnings)
    }
}
